386: def _prepare_query(sql_text, params, null_text):
387:     """校验三类入口共用的查询输入，返回 (可执行语句, 绑定字典)。
388: 
389:     集中 export_csv、export_html 与 preview_csv 同一份拒绝规则及先后
390:     顺序：null_text 类型 → 参数字典 → 单条 SELECT → 占位符绑定。任何
391:     失败都抛 ValueError；此阶段只做纯输入校验，不检查输出目标，也不
392:     打开源库。preview_csv 特有的行数校验、export_html 特有的说明类型
393:     校验由调用方在本函数之前先行完成，因此三者的错误优先级保持原状。
394:     """
395:     if not isinstance(null_text, str):
396:         raise ValueError(
397:             "null_text 必须是字符串，收到 %s" % type(null_text).__name__
398:         )
399:     params = validate_params(params)
400:     statement = validate_single_select(sql_text)
401:     bound = bind_params(statement, params)
402:     return statement, bound
