450: def _run_readonly_query(db_path, statement, bound):
451:     """以只读连接打开源库、取回全部结果，并保证随后关闭连接。
452: 
453:     三类入口共用同一份只读取数流程：open_readonly 负责在文件缺失或
454:     损坏时抛 ValueError 且不创建新库；_fetch_rows 统一开始执行与惰性
455:     求值两个时点的 sqlite3.Error 为 ValueError。连接在 try/finally
456:     中关闭，成功或失败都不会遗留在手的数据库连接。
457:     """
458:     conn = open_readonly(db_path)
459:     try:
460:         return _fetch_rows(conn, statement, bound)
461:     finally:
462:         conn.close()
